YEARS=list(range(2018,2027))
# integrity: every Q1..80 assigned exactly once per year
for y in YEARS:
    keys=list(LM[y])+list(SI[y])+list(OS[y])
    assert sorted(keys)==list(range(1,81)), (y, sorted(set(range(1,81))-set(keys)), [k for k in keys if keys.count(k)>1])
print("INTEGRITY OK: all 9 years x 80 items assigned exactly once =", 9*80)

def table(D, order):
    cnt={t:{y:0 for y in YEARS} for t in order}
    for y in YEARS:
        for q,t in D[y].items(): cnt[t][y]+=1
    return cnt

lmord=[f'LM-{i}' for i in range(1,12)]
siord=[f'SI-{i}' for i in range(1,21)]
osord=[f'OS-{i}' for i in range(1,12)]
tabs={'LM':table(LM,lmord),'SI':table(SI,siord),'OS':table(OS,osord)}
json.dump({k:{t:{str(y):v for y,v in d.items()} for t,d in tb.items()} for k,tb in tabs.items()}, open('counts.json','w'))

for part,tb in tabs.items():
    print(f"\n=== {part} ===")
    print("topic  "+" ".join(str(y)[2:] for y in YEARS)+"  TOT")
    for t,d in tb.items():
        tot=sum(d.values())
        print(f"{t:6} "+" ".join(f"{d[y]:2d}" for y in YEARS)+f"   {tot:3d}")
    print("YRTOT  "+" ".join(f"{sum(tb[t][y] for t in tb):2d}" for y in YEARS)+f"   {sum(sum(d.values()) for d in tb.values()):3d}")
